// Degree-16 Horner polynomial, mod 2^16, FULLY PIPELINED (one register per
// stage, with the input stage inline) -> short per-stage path, higher Fmax.
// Functionally identical to the reference, different surface form.
module poly16_v13_8b (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [7:0]  x,
    output reg  [15:0] y
);
    reg [15:0] r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15;
    always @(posedge clk) begin
        if (!rst_n) begin r0 <= 16'd0; r1 <= 16'd0; r2 <= 16'd0; r3 <= 16'd0; r4 <= 16'd0; r5 <= 16'd0; r6 <= 16'd0; r7 <= 16'd0; r8 <= 16'd0; r9 <= 16'd0; r10 <= 16'd0; r11 <= 16'd0; r12 <= 16'd0; r13 <= 16'd0; r14 <= 16'd0; r15 <= 16'd0; y <= 16'd0; end
        else begin
            r0 <= 16'd45;
            r1 <= r0 * x + 16'd67;
            r2 <= r1 * x + 16'd56;
            r3 <= r2 * x + 16'd54;
            r4 <= r3 * x + 16'd26;
            r5 <= r4 * x + 16'd74;
            r6 <= r5 * x + 16'd47;
            r7 <= r6 * x + 16'd10;
            r8 <= r7 * x + 16'd96;
            r9 <= r8 * x + 16'd73;
            r10 <= r9 * x + 16'd22;
            r11 <= r10 * x + 16'd53;
            r12 <= r11 * x + 16'd23;
            r13 <= r12 * x + 16'd53;
            r14 <= r13 * x + 16'd77;
            r15 <= r14 * x + 16'd32;
            y <= r15 * x;
        end
    end
endmodule
